1	// Per-node capacity / utilization math for the node-capacity warning feature.
2	//
3	// Plain (non-"use server") module — safe to import from admin server components
4	// (the Compute-nodes and Web-hosting pages render bars off it) AND from the
5	// worker sweep (worker/monitor.ts → nodeCapacitySweep raises/clears NodeAlerts
6	// off it). No mutations here; the alert lifecycle lives in the worker so this
7	// file stays a pure-ish reader other surfaces can share, exactly like the
8	// read-only helpers in lib/monitoring.ts.
9	//
10	// TWO NODE TYPES, ONE MODEL. Nxeon schedules customer VMs onto Proxmox `Node`s
11	// and shared-hosting accounts onto `HostingNode`s. Both fill up and both refuse
12	// new work when they do, so both are reduced to the same shape: a list of
13	// per-DIMENSION utilization percentages (CPU/RAM/DISK for Proxmox, ACCOUNTS/DISK
14	// for hosting) that the thresholds below turn into OK / WARN / CRITICAL.
15	//
16	// ALLOCATION vs REAL USAGE. For each dimension we take the WORSE of two numbers:
17	//   - allocation: what the DB has COMMITTED to the node (sum of every server's
18	//     plan RAM/disk/vCPU, or the account count). This is what makes the NEXT
19	//     provision fail — a node can be 100% committed while barely warm.
20	//   - real usage: what Proxmox actually reports in use right now (RAM/CPU/disk),
21	//     which is what makes a node DEGRADE.
22	// Warning on max(alloc, real) means we fire on whichever ceiling is hit first,
23	// which is the honest "add a node before this bites" signal the feature exists
24	// to give.
25	
26	import { db } from "./db";
27	import { nodeRamUsage, nodeStorageUsage, type NodeRam, type StorageUsage } from "./monitoring";
28	import { effectiveDiskGB } from "./extra-disk";
29	import { getSettingInt } from "./settings";
30	
31	const MB = 1024 * 1024;
32	const GB = 1024 ** 3;
33	
34	export type CapSeverity = "OK" | "WARN" | "CRITICAL";
35	export type CapDimension = "CPU" | "RAM" | "DISK" | "ACCOUNTS";
36	export type NodeKind = "PROXMOX" | "HOSTING";
37	
38	export type NodeThresholds = { warnPct: number; critPct: number };
39	
40	export const NODE_CAP_DEFAULT_WARN = 80;
41	export const NODE_CAP_DEFAULT_CRIT = 90;
42	
43	/**
44	 * Hysteresis: an OPEN alert only auto-resolves once utilization falls this many
45	 * points BELOW the WARN threshold. Without the gap a node parked right on the
46	 * line (79 ⇄ 81) would flap open/closed every sweep and bury the operator in
47	 * churn. Env-overridable for tuning without a redeploy.
48	 */
49	export const NODE_CAP_RESOLVE_MARGIN = Number(process.env.NXEON_NODE_ALERT_RESOLVE_MARGIN ?? 5);
50	
51	/**
52	 * A persistent (unchanged-severity) condition re-notifies at most once per this
53	 * many hours — the debounce that stops "node stuck at 92%" emailing ops every
54	 * 10-minute sweep. A NEW alert and a WARN⇄CRITICAL change always notify
55	 * immediately regardless of the cooldown.
56	 */
57	export const NODE_CAP_COOLDOWN_HOURS = Number(process.env.NXEON_NODE_ALERT_COOLDOWN_HOURS ?? 6);
58	
59	/**
60	 * Every server status EXCEPT DELETING still holds committed capacity on its node
61	 * — its VM (and its RAM/disk reservation) exists until the delete completes. This
62	 * matches the exclusion the existing scheduler and infra pages already use
63	 * (`status: { not: "DELETING" }`), so the utilization shown here agrees with what
64	 * scheduleNode commits against.
65	 */
66	const VPS_COMMITTED_EXCLUDE = ["DELETING"] as const;
67	/** Hosting-account statuses that still occupy a slot / quota on their node. */
68	const HOSTING_LIVE_STATUSES = ["PENDING", "PROVISIONING", "ACTIVE", "SUSPENDED"] as const;
69	
70	/**
71	 * Resolve the admin-configured thresholds, clamped so they are always usable:
72	 * both in 1..100, and CRITICAL never below WARN (a CRITICAL under WARN would make
73	 * the amber band unreachable and every warn instantly read critical).
74	 */
75	export async function nodeThresholds(): Promise<NodeThresholds> {
76	  let warnPct = await getSettingInt("node_warn_pct", NODE_CAP_DEFAULT_WARN);
77	  let critPct = await getSettingInt("node_critical_pct", NODE_CAP_DEFAULT_CRIT);
78	  if (!Number.isFinite(warnPct) || warnPct < 1 || warnPct > 100) warnPct = NODE_CAP_DEFAULT_WARN;
79	  if (!Number.isFinite(critPct) || critPct < 1 || critPct > 100) critPct = NODE_CAP_DEFAULT_CRIT;
80	  if (critPct < warnPct) critPct = warnPct;
81	  return { warnPct, critPct };
82	}
83	
84	/** Bucket a utilization percent into OK / WARN / CRITICAL. */
85	export function severityFor(pct: number, t: NodeThresholds): CapSeverity {
86	  if (pct >= t.critPct) return "CRITICAL";
87	  if (pct >= t.warnPct) return "WARN";
88	  return "OK";
89	}
90	
91	/** The percent below which an OPEN alert is allowed to auto-resolve. */
92	export function resolveFloor(t: NodeThresholds): number {
93	  return Math.max(0, t.warnPct - NODE_CAP_RESOLVE_MARGIN);
94	}
95	
96	export type DimUtil = {
97	  dimension: CapDimension;
98	  /** The value thresholded — the worse of allocation and real usage. */
99	  pct: number;
100	  /** DB-committed percent (null when the dimension has no allocation basis). */
101	  allocPct: number | null;
102	  /** Live-usage percent from Proxmox (null when unreachable / not applicable). */
103	  realPct: number | null;
104	  /** Short human breakdown, e.g. "48 / 56 GB committed · 61% used". */
105	  detail: string;
106	};
107	
108	export type NodeUtil = {
109	  kind: NodeKind;
110	  id: string;
111	  name: string;
112	  enabled: boolean;
113	  /** For Proxmox: node status endpoint reachable. Hosting is DB-only → always true. */
114	  reachable: boolean;
115	  dims: DimUtil[];
116	  /** Worst dimension percent across `dims` (0 when there are none). */
117	  worstPct: number;
118	  severity: CapSeverity;
119	};
120	
121	function pct(part: number, whole: number): number | null {
122	  if (!(whole > 0)) return null;
123	  return (part / whole) * 100;
124	}
125	
126	/** Combine allocation + real into the thresholded value (worse of the two). */
127	function worse(allocPct: number | null, realPct: number | null): number {
128	  return Math.max(allocPct ?? 0, realPct ?? 0);
129	}
130	
131	function rollup(dims: DimUtil[], t: NodeThresholds): { worstPct: number; severity: CapSeverity } {
132	  const worstPct = dims.reduce((m, d) => Math.max(m, d.pct), 0);
133	  return { worstPct, severity: severityFor(worstPct, t) };
134	}
135	
136	// ---------------------------------------------------------------------------
137	// Proxmox compute nodes
138	// ---------------------------------------------------------------------------
139	
140	/**
141	 * Utilization for every registered Proxmox node.
142	 *
143	 * RAM is always computable (allocation from `Node.capacityRamMB` + the sum of
144	 * each live server's `plan.ramMB`; real usage from the node status endpoint when
145	 * reachable). CPU and DISK need Proxmox to be reachable for their denominator
146	 * (physical thread count / storage pool size), so on an unreachable node they are
147	 * simply omitted rather than guessed — `reachable:false` tells the UI and the
148	 * sweep to treat their absence as "unknown", never as "recovered".
149	 */
150	export async function proxmoxNodeUtil(t: NodeThresholds): Promise<NodeUtil[]> {
151	  const nodes = await db.node.findMany({
152	    orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }],
153	    include: {
154	      servers: {
155	        where: { status: { notIn: [...VPS_COMMITTED_EXCLUDE] } },
156	        select: {
157	          extraDiskGB: true,
158	          plan: { select: { cpuCores: true, ramMB: true, diskGB: true } },
159	        },
160	      },
161	    },
162	  });
163	
164	  // Real usage, best-effort. Keyed by node NAME — nodeRamUsage/nodeStorageUsage
165	  // label every row with `Node.name` (see lib/monitoring.ts nodeTargets).
166	  let ramRows: NodeRam[] = [];
167	  let storageRows: StorageUsage[] = [];
168	  try {
169	    ramRows = await nodeRamUsage();
170	  } catch {
171	    /* leave empty — every node reads unreachable */
172	  }
173	  try {
174	    storageRows = await nodeStorageUsage();
175	  } catch {
176	    /* leave empty */
177	  }
178	  const ramByNode = new Map(ramRows.map((r) => [r.node, r]));
179	
180	  return nodes.map((n) => {
181	    const committedRamMB = n.servers.reduce((s, sv) => s + sv.plan.ramMB, 0);
182	    const committedDiskGB = n.servers.reduce(
183	      (s, sv) => s + effectiveDiskGB(sv.plan.diskGB, sv.extraDiskGB),
184	      0,
185	    );
186	    const committedVcpu = n.servers.reduce((s, sv) => s + sv.plan.cpuCores, 0);
187	
188	    const real = ramByNode.get(n.name);
189	    const reachable = !!real?.reachable;
190	    // The node's own VM-disk pool (storageNvme) is the disk denominator.
191	    const vmStorage = storageRows.find((s) => s.node === n.name && s.storage === n.storageNvme);
192	
193	    const dims: DimUtil[] = [];
194	
195	    // RAM — allocation always available; real when reachable.
196	    {
197	      const allocPct = pct(committedRamMB, n.capacityRamMB);
198	      const realPct = reachable && real ? real.ratio * 100 : null;
199	      const p = worse(allocPct, realPct);
200	      const parts = [
201	        `${(committedRamMB / 1024).toFixed(0)} / ${(n.capacityRamMB / 1024).toFixed(0)} GB committed`,
202	      ];
203	      if (realPct !== null) parts.push(`${Math.round(realPct)}% used`);
204	      dims.push({ dimension: "RAM", pct: p, allocPct, realPct, detail: parts.join(" · ") });
205	    }
206	
207	    // CPU — real usage is the signal (vCPU is normally overcommitted, so an
208	    // allocation ratio is context, not an alarm). Only present when reachable.
209	    if (reachable && real) {
210	      const realPct = real.cpu * 100;
211	      const allocPct = real.cores > 0 ? (committedVcpu / real.cores) * 100 : null;
212	      const parts = [`${Math.round(realPct)}% used`];
213	      if (allocPct !== null) {
214	        parts.push(`${committedVcpu} vCPU / ${real.cores} threads (${Math.round(allocPct)}% committed)`);
215	      }
216	      // CPU is thresholded on REAL load only; overcommit alloc is informational.
217	      dims.push({ dimension: "CPU", pct: realPct, allocPct, realPct, detail: parts.join(" · ") });
218	    }
219	
220	    // DISK — needs the pool size from Proxmox. Allocation = committed effective
221	    // disk vs pool total; real = pool used vs pool total. Worse of the two.
222	    if (vmStorage?.reachable && vmStorage.total > 0) {
223	      const allocPct = pct(committedDiskGB * GB, vmStorage.total);
224	      const realPct = vmStorage.ratio * 100;
225	      const p = worse(allocPct, realPct);
226	      const parts = [
227	        `${committedDiskGB} GB committed of ${(vmStorage.total / GB).toFixed(0)} GB`,
228	        `${Math.round(realPct)}% used`,
229	      ];
230	      dims.push({ dimension: "DISK", pct: p, allocPct, realPct, detail: parts.join(" · ") });
231	    }
232	
233	    return {
234	      kind: "PROXMOX" as const,
235	      id: n.id,
236	      name: n.name,
237	      enabled: n.enabled,
238	      reachable,
239	      dims,
240	      ...rollup(dims, t),
241	    };
242	  });
243	}
244	
245	// ---------------------------------------------------------------------------
246	// Shared-hosting nodes
247	// ---------------------------------------------------------------------------
248	
249	/**
250	 * Utilization for every HostingNode. Purely DB-derived (the accounts and their
251	 * quotas live in our own tables), so it is always reachable:
252	 *   - ACCOUNTS: live account count vs `HostingNode.maxAccounts` — the hard
253	 *     scheduler cap; the next account is refused once it's full.
254	 *   - DISK: worse of committed quota (Σ diskQuotaMB) and measured usage
255	 *     (Σ diskUsedMB, filled by hostingUsageSweep) vs `diskTotalGB`.
256	 */
257	export async function hostingNodeUtil(t: NodeThresholds): Promise<NodeUtil[]> {
258	  const nodes = await db.hostingNode.findMany({ orderBy: { name: "asc" } });
259	
260	  return Promise.all(
261	    nodes.map(async (n) => {
262	      const [count, agg] = await Promise.all([
263	        db.hostingAccount.count({
264	          where: { hostingNodeId: n.id, status: { in: [...HOSTING_LIVE_STATUSES] } },
265	        }),
266	        db.hostingAccount.aggregate({
267	          where: { hostingNodeId: n.id, status: { in: [...HOSTING_LIVE_STATUSES] } },
268	          _sum: { diskQuotaMB: true, diskUsedMB: true },
269	        }),
270	      ]);
271	
272	      const totalDiskMB = n.diskTotalGB * 1024;
273	      const quotaMB = agg._sum.diskQuotaMB ?? 0;
274	      const usedMB = agg._sum.diskUsedMB ?? 0;
275	
276	      const dims: DimUtil[] = [];
277	
278	      // ACCOUNTS
279	      {
280	        const allocPct = pct(count, n.maxAccounts);
281	        const p = allocPct ?? 0;
282	        dims.push({
283	          dimension: "ACCOUNTS",
284	          pct: p,
285	          allocPct,
286	          realPct: null,
287	          detail: `${count} / ${n.maxAccounts} accounts`,
288	        });
289	      }
290	
291	      // DISK
292	      {
293	        const allocPct = pct(quotaMB, totalDiskMB);
294	        const realPct = pct(usedMB, totalDiskMB);
295	        const p = worse(allocPct, realPct);
296	        const parts = [`${(quotaMB / 1024).toFixed(0)} GB quota of ${n.diskTotalGB} GB`];
297	        if (realPct !== null) parts.push(`${(usedMB / 1024).toFixed(0)} GB used`);
298	        dims.push({ dimension: "DISK", pct: p, allocPct, realPct, detail: parts.join(" · ") });
299	      }
300	
301	      return {
302	        kind: "HOSTING" as const,
303	        id: n.id,
304	        name: n.name,
305	        enabled: n.enabled,
306	        reachable: true,
307	        dims,
308	        ...rollup(dims, t),
309	      };
310	    }),
311	  );
312	}
313	
314	/** Every node (both kinds) with its utilization, plus the resolved thresholds. */
315	export async function allNodeUtil(): Promise<{ thresholds: NodeThresholds; nodes: NodeUtil[] }> {
316	  const thresholds = await nodeThresholds();
317	  const [proxmox, hosting] = await Promise.all([
318	    proxmoxNodeUtil(thresholds),
319	    hostingNodeUtil(thresholds),
320	  ]);
321	  return { thresholds, nodes: [...proxmox, ...hosting] };
322	}
323	
324	/** Color for a utilization bar, matching the WARN/CRITICAL bands. */
325	export function capBarColor(sev: CapSeverity): string {
326	  if (sev === "CRITICAL") return "#ef4444";
327	  if (sev === "WARN") return "#f59e0b";
328	  return "#34d399";
329	}
330	
331	export { MB, GB };
332

