2185:model ServerDiskSample {

1	import { db } from "./db";
2	import { pveFor } from "./proxmox";
3	import { effectiveDiskGB } from "./extra-disk";
4	
5	/**
6	 * Host capacity accounting for the deploy flow.
7	 *
8	 * We oversell RAM (the scarce resource) by a factor, but never past the
9	 * host's physical RAM minus a reserve for the hypervisor itself. Disk on
10	 * `vmdata` is large relative to plan sizes, so RAM is the binding constraint.
11	 *
12	 * All values are overridable via env so staging/prod can differ without code
13	 * changes; the defaults match the production KS-GAME box (64 GB RAM).
14	 */
15	export const HOST_RAM_MB = Number(process.env.NXEON_HOST_RAM_MB ?? 64000);
16	export const HOST_RAM_RESERVE_MB = Number(process.env.NXEON_HOST_RAM_RESERVE_MB ?? 8000);
17	export const RAM_OVERSELL_FACTOR = Number(process.env.NXEON_RAM_OVERSELL ?? 1.5);
18	
19	/**
20	 * Usable NVMe VM-disk pool in GB, used as a fallback when the live Proxmox
21	 * storage total can't be read. Unlike RAM we do NOT oversell disk — thin
22	 * provisioning already lets guests share the pool, so we commit against the
23	 * real pool size minus a safety margin.
24	 */
25	export const HOST_DISK_GB = Number(process.env.NXEON_HOST_DISK_GB ?? 800);
26	/** Fraction of usable disk we allow to be committed before refusing deploys. */
27	export const DISK_SAFETY_RATIO = Number(process.env.NXEON_DISK_SAFETY ?? 0.9);
28	/**
29	 * VM disk on ZFS is THIN-provisioned: a guest only consumes what it actually
30	 * writes, not its full nominal plan size. So committing raw plan sizes against
31	 * the pool wildly under-counts real capacity (e.g. four ~2 GB-used guests read
32	 * as 275 GB "committed"). We therefore oversell nominal disk like RAM, and rely
33	 * on the live free-space floor below as the true overflow guard.
34	 */
35	export const DISK_OVERSELL_FACTOR = Number(process.env.NXEON_DISK_OVERSELL ?? 3);
36	/** Refuse deploys once the pool's REAL free space would sit below this (GB). */
37	export const DISK_MIN_FREE_GB = Number(process.env.NXEON_DISK_MIN_FREE_GB ?? 20);
38	
39	/** Effective committable RAM ceiling in MB after reserve + oversell. */
40	export function ramCeilingMB(): number {
41	  return Math.max(0, (HOST_RAM_MB - HOST_RAM_RESERVE_MB) * RAM_OVERSELL_FACTOR);
42	}
43	
44	export type CapacitySnapshot = {
45	  committedRamMB: number;
46	  committedDiskGB: number;
47	  ceilingRamMB: number;
48	  serverCount: number;
49	  /** 0..1 fraction of the RAM ceiling already committed. */
50	  ramUtilization: number;
51	  /** true once committed RAM is within 15% of the ceiling. */
52	  nearCapacity: boolean;
53	};
54	
55	/** Sum committed RAM/disk across all servers that are not being torn down. */
56	export async function capacitySnapshot(): Promise<CapacitySnapshot> {
57	  const servers = await db.server.findMany({
58	    where: { status: { not: "DELETING" } },
59	    select: { extraDiskGB: true, plan: { select: { ramMB: true, diskGB: true } } },
60	  });
61	  const committedRamMB = servers.reduce((sum, s) => sum + s.plan.ramMB, 0);
62	  const committedDiskGB = servers.reduce((sum, s) => sum + effectiveDiskGB(s.plan.diskGB, s.extraDiskGB), 0);
63	  const ceilingRamMB = ramCeilingMB();
64	  const ramUtilization = ceilingRamMB > 0 ? committedRamMB / ceilingRamMB : 1;
65	  return {
66	    committedRamMB,
67	    committedDiskGB,
68	    ceilingRamMB,
69	    serverCount: servers.length,
70	    ramUtilization,
71	    nearCapacity: ramUtilization >= 0.85,
72	  };
73	}
74	
75	/**
76	 * Would deploying `planId` push committed RAM past the oversell ceiling?
77	 * Returns { ok:false, reason } when the host cannot take the new server.
78	 */
79	export async function capacityCheck(planId: string): Promise<{ ok: boolean; reason?: string }> {
80	  const plan = await db.plan.findUnique({ where: { id: planId }, select: { ramMB: true, name: true } });
81	  if (!plan) return { ok: false, reason: "Plan not found." };
82	
83	  const snap = await capacitySnapshot();
84	  const projected = snap.committedRamMB + plan.ramMB;
85	  if (projected > snap.ceilingRamMB) {
86	    return {
87	      ok: false,
88	      reason:
89	        "The host is at capacity — not enough RAM headroom to deploy this plan right now. " +
90	        "Please try a smaller plan or contact support.",
91	    };
92	  }
93	  return { ok: true };
94	}
95	
96	/**
97	 * Would committing `addDiskGB` more of VM disk overflow the node's usable
98	 * storage? Mirrors `capacityCheck` but for disk: sums committed plan disk on
99	 * the node and compares against the usable NVMe pool times a safety ratio.
100	 *
101	 * Usable pool size is read live from Proxmox (`storageNvme` status) when the
102	 * node is reachable, falling back to `HOST_DISK_GB`. Pass `nodeId = null` to
103	 * check against all non-deleting servers / the primary node.
104	 */
105	export async function diskCapacityCheck(
106	  nodeId: string | null | undefined,
107	  addDiskGB: number
108	): Promise<{ ok: boolean; reason?: string }> {
109	  const servers = await db.server.findMany({
110	    where: { status: { not: "DELETING" }, ...(nodeId ? { nodeId } : {}) },
111	    select: { extraDiskGB: true, plan: { select: { diskGB: true } } },
112	  });
113	  // Committed disk counts the EFFECTIVE size of every server (plan + purchased
114	  // extra), otherwise expansions would silently oversubscribe the pool.
115	  const committedDiskGB = servers.reduce((sum, s) => sum + effectiveDiskGB(s.plan.diskGB, s.extraDiskGB), 0);
116	
117	  // Resolve usable pool size + REAL usage — prefer the live Proxmox NVMe pool.
118	  let usableGB = HOST_DISK_GB;
119	  let freeGB: number | null = null; // real free space (total − used), when known
120	  try {
121	    const n = nodeId
122	      ? await db.node.findUnique({ where: { id: nodeId } })
123	      : await db.node.findFirst({ where: { isPrimary: true } });
124	    if (n) {
125	      const client = pveFor({
126	        apiUrl: n.apiUrl,
127	        pveNode: n.pveNode,
128	        tokenId: n.tokenId,
129	        tokenSecret: n.tokenSecret,
130	      });
131	      const st = await client.get(`/nodes/${n.pveNode}/storage/${n.storageNvme}/status`);
132	      const totalGB = Number(st?.total ?? 0) / 1024 ** 3;
133	      const usedGB = Number(st?.used ?? 0) / 1024 ** 3;
134	      if (totalGB > 0) usableGB = totalGB;
135	      if (totalGB > 0 && usedGB >= 0) freeGB = Math.max(0, totalGB - usedGB);
136	    }
137	  } catch {
138	    // Proxmox unreachable — fall back to the configured HOST_DISK_GB (no live free).
139	  }
140	
141	  // Guard 1 (the real one): never provision into a genuinely near-full pool.
142	  // Thin guests consume only what they write, so live free space is the true
143	  // constraint — not the sum of nominal plan sizes.
144	  if (freeGB != null && freeGB - addDiskGB < DISK_MIN_FREE_GB) {
145	    return {
146	      ok: false,
147	      reason:
148	        "This node's storage pool is nearly full — we can't safely deploy this plan right now. " +
149	        "Please choose a smaller disk or contact support so we can add capacity.",
150	    };
151	  }
152	
153	  // Guard 2 (backstop): cap nominal thin overcommit so oversell can't run away
154	  // even if the live free-space read is unavailable.
155	  const nominalCeilingGB = usableGB * DISK_SAFETY_RATIO * DISK_OVERSELL_FACTOR;
156	  if (committedDiskGB + addDiskGB > nominalCeilingGB) {
157	    return {
158	      ok: false,
159	      reason:
160	        "Not enough disk headroom on this node to deploy this plan right now. " +
161	        "Please choose a smaller disk or contact support.",
162	    };
163	  }
164	  return { ok: true };
165	}
