393	      `could not write the cloud-init snippet ${SNIPPET_DIR}/nxeon-${vmid}.yaml (${e?.message ?? e}). ` +
394	        `The VM would boot with no root password, no SSH key and no setup script, so provisioning ` +
395	        `stopped here rather than reporting a server that would not be usable.`
396	    );
397	  }
