399	  const keys = await db.sshKey.findMany({ where: { userId: server.userId } });
400	  const sshkeys = keys.length
401	    ? encodeURIComponent(keys.map((k) => k.publicKey.trim()).join("\n"))
402	    : undefined;
403	  const cfg: Record<string, any> = {
404	    cores: server.plan.cpuCores,
405	    memory: server.plan.ramMB,
406	    ciuser: "root",
407	    cipassword: password,
408	    sshkeys,
409	    nameserver: "1.1.1.1 8.8.8.8",
410	    onboot: 1,
411	    cicustom: `vendor=${SNIPPET_STORAGE}:snippets/nxeon-${vmid}.yaml`,
412	    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
413	  };
414	  if (dedicated) {
415	    // Public bridge + OVH Virtual MAC; failover IP as /32 with the host's OVH gateway.
416	    cfg.net0 = `virtio=${dedicated.virtualMac},bridge=vmbr0`;
417	    cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
418	  } else {
419	    // Node-aware gateway: a second node with a different subnet must not get the primary's gateway.
