432	  // Port forwarding is what makes the `ssh root@host -p <port>` line below true
433	  // for a NAT server. If it cannot be proved, the readiness message says so
434	  // instead of printing a command that will hang (H5 + M7 #10). Not fatal: the
435	  // VM itself is fine and a failed PROVISION would flip it to ERROR and release
436	  // its IP, which is a worse outcome than a missing forward.
437	  let natError: Error | null = null;
438	  if (!SANDBOX && !dedicated) natError = await syncPortForwardsBestEffort(`provision ${server.hostname}`);
439	
440	  const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
441	  await conn.waitForTask(startUpid);
442	
443	  // `waitForTask` proves Proxmox accepted the start, nothing more. Ask the guest
