500	/**
501	 * Tear down a VM. Idempotent and verified — see `destroyVmIdempotent` in
502	 * lib/proxmox.ts for the incident and the ladder. The bare version of this
503	 * function threw on an already-absent VM, which is what made a retried REINSTALL
504	 * destroy a customer's server permanently.
505	 */
506	async function destroyVm(conn: any, vmid: number): Promise<DestroyOutcome> {
507	  const host: VmDestroyHost = {
508	    probe: async (id) => {
509	      try {
510	        await conn.vmStatus(id);
511	        return "present";
512	      } catch (e) {
513	        // Only a vmid-anchored "config does not exist" proves absence. Anything
514	        // else (auth, network, a locked node) is genuinely unknown and must not
515	        // be read as "already gone".
516	        return isVmAbsentError(e, id) ? "absent" : "unknown";
517	      }
518	    },
519	    stop: async (id) => {
520	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${id}/status/stop`, {});
521	      await conn.waitForTask(stopUpid);
522	    },
523	    destroy: async (id) => {
524	      const delUpid = await conn.del(`/nodes/${conn.node}/qemu/${id}`, {
525	        "destroy-unreferenced-disks": 1,
526	        purge: 1,
527	      });
528	      await conn.waitForTask(delUpid, 600_000);
529	    },
530	  };
531	  return destroyVmIdempotent(host, vmid);
532	}
