534	async function remove(job: Job) {
535	  const server = await loadServer(job);
536	  const { conn } = await nodeFor(server);
537	  if (!SANDBOX && server.vmid) {
538	    // `destroyVm` is now idempotent and VERIFIES the VM is gone before returning,
539	    // so the absent case no longer needs to be caught here at all. The catch that
540	    // remains is narrowed to this vmid: it used to swallow any error containing
541	    // "does not exist", which also matches `storage 'vmdata' does not exist` and
542	    // `volume ... does not exist` — errors that mean the VM is very much still
543	    // running. On one of those the handler proceeded to delete the Server row and
544	    // every Volume row pinned to it, leaving a live VM with no database record:
545	    // invisible to billing, invisible to the panel, still holding the customer's
546	    // data and impossible to reach through any surface we own.
547	    try {
548	      await destroyVm(conn, server.vmid);
549	    } catch (e: any) {
550	      if (!isVmAbsentError(e, server.vmid)) throw e;
551	    }
552	    // Best-effort: remove the per-server cloud-init snippet
553	    await unlink(`${SNIPPET_DIR}/nxeon-${server.vmid}.yaml`).catch(() => {});
554	  }
555	  // Return any dedicated IP to the pool (deletes the OVH Virtual MAC).
556	  if (!SANDBOX) await releaseDedicatedIp(server.id).catch((e) => console.error("[worker] release dedicated IP failed", e));
557	  // Any block-storage volume disk (vm-<vmid>-disk-N) was purged with the VM above.
558	  // Volume.server is SetNull, so the rows would otherwise survive with a dead
559	  // diskName and keep billing forever. Remove them and notify the owner. (The
560	  // reinstall guard already blocks the accidental case; a full server delete is an
561	  // intentional teardown, so we drop the volumes with it.)
562	  const orphanVolumes = await db.volume.findMany({ where: { serverId: server.id } });
563	  if (orphanVolumes.length > 0) {
564	    await db.volume.deleteMany({ where: { serverId: server.id } });
565	    for (const v of orphanVolumes) {
566	      await notify(
567	        v.userId,
568	        `Volume "${v.name}" was removed`,
569	        `${v.sizeGB} GB block storage was deleted along with server ${server.hostname}. Billing for it has stopped.`,
570	        "/dashboard/volumes",
571	      ).catch(() => {});
572	    }
573	  }
574	  // Detach this DELETE job (and any siblings) from the server FIRST, otherwise the
575	  // server.delete cascade removes THIS running Job row — the success-path
576	  // `job.update({id})` then throws P2025 and escapes runJob. Null serverId instead.
577	  await db.job.updateMany({ where: { serverId: server.id }, data: { serverId: null } });
578	  await db.server.delete({ where: { id: server.id } });
579	  // Best-effort BY NECESSITY: the server row is gone, so a throw here re-queues
580	  // DELETE, which then dies on "Server not found" and the sync is never retried
581	  // (H5's aggravating factor). The failure is logged in full rather than hidden.
582	  if (!SANDBOX) await syncPortForwardsBestEffort(`delete ${server.hostname}`);
583	}
