585	async function reinstall(job: Job) {
586	  const server = await loadServer(job);
587	  if (SANDBOX) {
588	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
589	    await notify(
590	      server.userId,
591	      `Server ${server.hostname} reinstalled (sandbox)`,
592	      "The sandbox server was reinstalled (no real VM was touched).",
593	      `/dashboard/servers/${server.id}`
594	    );
595	    return;
596	  }
597	  // DATA SAFETY (critical): a reinstall destroys the VM, and `destroyVm` runs
598	  // `qm destroy` with { "destroy-unreferenced-disks": 1, purge: 1 } — which wipes
599	  // EVERY disk the vmid owns, including attached block-storage Volume disks
600	  // (scsi1+, `vmdata:vm-<vmid>-disk-N`). A disk named `vm-<vmid>-disk-N` is owned
601	  // by that vmid, and both purge and the default destroy (which removes disks
602	  // referenced in config, incl. detached `unusedN` entries) delete it; there is no
603	  // Proxmox API to selectively spare it, and the reinstall re-clones onto the SAME
604	  // vmid, so we cannot GUARANTEE such a disk survives the destroy. Rather than risk
605	  // wiping a customer's data, BLOCK the reinstall until the volume(s) are detached.
606	  // Detaching moves the disk to an "unused" entry (data preserved on storage) and it
607	  // can be re-attached after the reinstall. This runs BEFORE any status change or
608	  // destructive call, so a blocked reinstall touches nothing.
609	  //
610	  // Match on `serverId` ALONE — NOT `status: "ATTACHED"`. Detaching keeps
611	  // `serverId` set (see worker/volumes.ts) so the volume can be re-attached, and
612	  // the disk remains owned by this vmid as an `unusedN` entry. PVE's destroy_vm
613	  // passes `include_unused => 1`, so it frees those too. Filtering on ATTACHED
614	  // let the worst path through: fill a volume, Detach (the UI says "Data is
615	  // preserved."), Reinstall — guard sees nothing attached, purge takes the data.
616	  // Detaching is therefore NOT sufficient protection, and telling the customer to
617	  // detach was wrong advice; they must delete the volume (which destroys just
618	  // that disk, deliberately) or move it to another server first.
619	  const pinnedVolumes = await db.volume.findMany({
620	    where: { serverId: server.id },
621	  });
622	  // Sandbox volumes have no real disk, so they cannot be purged and must not block.
623	  const realPinned = pinnedVolumes.filter(
624	    (v) => !(typeof v.diskName === "string" && v.diskName.startsWith("sandbox:"))
625	  );
626	  if (realPinned.length > 0) {
627	    const names = realPinned.map((v) => `"${v.name}"`).join(", ");
628	    throw new Error(
629	      `Remove your data volume(s) before reinstalling to protect their data: ${names}. ` +
630	        `Reinstalling purges every disk this server owns — including detached volumes ` +
631	        `that are still assigned to it — and that cannot be undone.`
632	    );
633	  }
634	
635	  const { conn } = await nodeFor(server);
636	  await db.server.update({ where: { id: server.id }, data: { status: "REINSTALLING" } });
637	  if (server.vmid) await destroyVm(conn, server.vmid);
638	  await provision(job);
639	}
