641	async function suspend(job: Job, unsuspend: boolean) {
642	  const server = await loadServer(job);
643	  if (SANDBOX) {
644	    if (unsuspend) {
645	      await db.server.update({ where: { id: server.id }, data: { status: "RUNNING", suspendedNote: null, suspendReason: null } });
646	    } else {
647	      await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
648	    }
649	    return;
650	  }
651	  const { conn, row: nodeRow } = await nodeFor(server);
652	  if (unsuspend) {
653	    // The dedicated IP was returned to the pool while suspended — re-allocate one
654	    // and reconfigure the public network before starting the VM back up.
655	    if (server.vmid) {
656	      const { getSettingBool: _sb } = await import("../lib/settings");
657	      const wantDedicated = server.wantsDedicatedIp || (await _sb("dedicated_ip_default", true));
658	      const alreadyHas = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
659	      let reconfigured = alreadyHas ? true : false;
660	      if (wantDedicated && ovhConfigured() && !alreadyHas) {
661	        try {
662	          const d = await allocateDedicatedIp(server.id, server.vmid);
663	          if (d) {
664	            await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
665	              net0: `virtio=${d.virtualMac},bridge=vmbr0`,
666	              ipconfig0: `ip=${d.address}/32,gw=${d.gateway}`,
667	            });
668	            await db.server.update({ where: { id: server.id }, data: { ipAddress: d.address, sshPort: null } });
669	            reconfigured = true;
670	          }
671	        } catch (e) {
672	          console.error("[worker] re-allocate dedicated IP on unsuspend failed; falling back to NAT", e);
673	        }
674	      }
675	      // If we couldn't (or didn't) give it a dedicated IP, its net0 still points at
676	      // the Virtual MAC + failover IP that suspend released back to the pool — that
677	      // IP may now belong to another server. Reconfigure onto shared NAT so it boots
678	      // with a valid, non-conflicting network instead of a dead public config.
679	      if (!reconfigured) {
680	        try {
681	          const ip = server.ipAddress ?? (await allocateIp(server.nodeId, server.id));
682	          const sshPort = server.sshPort ?? (await allocateSshPort(server.nodeId, server.id));
683	          await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
684	            net0: `virtio,bridge=${nodeRow?.bridge ?? "vmbr1"}`,
685	            ipconfig0: `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`,
686	          });
687	          await db.server.update({ where: { id: server.id }, data: { ipAddress: ip, sshPort } });
688	        } catch (e) {
689	          console.error("[worker] NAT fallback on unsuspend failed", e);
690	        }
691	      }
692	    }
693	    await db.server.update({ where: { id: server.id }, data: { status: "STOPPED", suspendedNote: null, suspendReason: null } });
694	    // Not fatal to the unsuspend itself (the customer is paid up and the VM must
695	    // come back), but never silent: an unproved sync is logged with its reason.
696	    if (!SANDBOX) await syncPortForwardsBestEffort(`unsuspend ${server.hostname}`);
697	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
698	    await conn.waitForTask(upid);
699	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
700	  } else {
701	    try {
702	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
703	      await conn.waitForTask(upid);
704	    } catch { /* may already be stopped */ }
705	    await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
706	    if (!SANDBOX) await syncPortForwardsBestEffort(`suspend ${server.hostname}`);
707	    // Return the dedicated IP to the pool while the server is suspended, so it
708	    // can be handed to a paying server. Re-allocated on unsuspend.
709	    if (ovhConfigured()) {
710	      try {
711	        const had = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
712	        if (had) {
713	          await releaseDedicatedIp(server.id);
714	          // MUST also clear the address off the server: `Server.ipAddress` is UNIQUE,
715	          // so leaving the released IP here makes the next server that claims it fail
716	          // with P2002 — that server then silently lands on NAT while its OVH Virtual
717	          // MAC stays allocated and billable. (NAT servers keep their private IP.)
718	          await db.server.update({
719	            where: { id: server.id },
720	            data: { ipAddress: null, ipv6: null },
721	          });
722	        }
723	      } catch (e) {
724	        console.error("[worker] release dedicated IP on suspend failed", e);
725	      }
726	    }
727	  }
728	}
