738	/**
739	 * Tell the customer their server failed to provision. Before this, a terminal
740	 * PROVISION failure flipped the server to ERROR and sent NOTHING — the customer
741	 * paid, then sat on a dead screen with a red dot and no explanation. Persists a
742	 * short human reason on `Server.provisionError` (surfaced in the ERROR banner on
743	 * the detail page), drops an in-app notification, and emails them. Best-effort on
744	 * every leg — a failed notification must never mask the underlying job failure.
745	 *
746	 * `error` is the redacted Job.error; we keep a trimmed copy for the customer.
747	 */
748	async function notifyProvisionFailed(
749	  server: { id: string; userId: string; hostname: string },
750	  error: string,
751	): Promise<void> {
752	  // A concise, customer-facing reason. The raw Job.error can be a 2000-char stack;
753	  // the first line is almost always the meaningful message.
754	  const reason = (error.split("\n")[0] || error).trim().slice(0, 300);
755	  try {
756	    await db.server.update({ where: { id: server.id }, data: { provisionError: reason } });
757	  } catch (e) {
758	    console.error("[worker] persist provisionError failed", e);
759	  }
760	  // If this VM backs a managed NxCloud, mark the wrapper FAILED too — otherwise a
761	  // failed nxcloud provision leaves the instance stuck on "setting up" forever
762	  // while the backing Server sits in ERROR. Its dashboard card reads this to show
763	  // the failed/retry state (components/customer/NxcloudClient.tsx).
764	  try {
765	    await db.nxCloudInstance.updateMany({
766	      where: { serverId: server.id, status: { notIn: ["DELETING", "ACTIVE"] } },
767	      data: { status: "FAILED", error: reason },
768	    });
769	  } catch (e) {
770	    console.error("[worker] mark nxcloud instance failed", e);
771	  }
772	  await notify(
773	    server.userId,
774	    `We couldn't set up ${server.hostname}`,
775	    `Provisioning failed and our team has been notified. You can retry it or contact support from the server page.`,
776	    `/dashboard/servers/${server.id}`,
777	  );
778	  try {
779	    const { sendMail, emails } = await import("../lib/mailer");
780	    const user = await db.user.findUnique({ where: { id: server.userId }, select: { email: true } });
781	    if (user?.email) {
782	      const tpl = emails.provisionFailed({ hostname: server.hostname, reason });
783	      await sendMail({
784	        to: user.email,
785	        subject: tpl.subject,
786	        html: tpl.html,
787	        template: tpl.template,
788	        userId: server.userId,
789	        // No `kind` → always send. A paid-for server that failed to build is a
790	        // service-delivery failure the customer must hear about.
791	      });
792	    }
793	  } catch (e) {
794	    console.error("[worker] provision-failure email failed", e);
795	  }
796	}
