798	async function resize(job: Job) {
799	  const server = await loadServer(job);
800	  const payload = (job.payload ?? {}) as { planId?: string };
801	  const newPlan = await db.plan.findUnique({ where: { id: payload.planId ?? "" } });
802	  if (!newPlan) throw new Error("resize: target plan not found");
803	  if (newPlan.diskGB < server.plan.diskGB) throw new Error("resize: disk can only grow");
804	
805	  // Any separately-purchased extra disk is ADDITIVE to whichever plan the server
806	  // sits on, so it survives the plan change untouched — `Server.extraDiskGB` is
807	  // never written here. Sizes below are therefore always the EFFECTIVE size
808	  // (new plan + extra); using the bare plan size would ask Proxmox to SHRINK the
809	  // disk of any server carrying extra storage, and the resize would hard-fail.
810	  const newTotalDiskGB = effectiveDiskGB(newPlan.diskGB, server.extraDiskGB);
811	  const currentTotalDiskGB = effectiveDiskGB(server.plan.diskGB, server.extraDiskGB);
812	  const diskLine =
813	    server.extraDiskGB > 0
814	      ? `${newTotalDiskGB} GB disk (${newPlan.diskGB} GB plan + ${server.extraDiskGB} GB added storage)`
815	      : `${newPlan.diskGB} GB disk`;
816	
817	  if (SANDBOX) {
818	    await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
819	    await notify(server.userId, `Server ${server.hostname} resized to ${newPlan.name}`,
820	      `${newPlan.cpuCores} vCPU / ${newPlan.ramMB / 1024} GB RAM / ${diskLine}`,
821	      `/dashboard/servers/${server.id}`);
822	    return;
823	  }
824	
825	  const { conn } = await nodeFor(server);
826	  const wasRunning = server.status === "RUNNING";
827	  await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
828	    cores: newPlan.cpuCores,
829	    memory: newPlan.ramMB,
830	  });
831	  if (newTotalDiskGB > currentTotalDiskGB) {
832	    await conn.put(`/nodes/${conn.node}/qemu/${server.vmid}/resize`, {
833	      disk: "scsi0",
834	      size: `${newTotalDiskGB}G`,
835	    });
836	  }
837	  await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
838	  // CPU/RAM changes need a power cycle to apply
839	  if (wasRunning) {
840	    try {
