981	async function backupCreate(job: Job) {
982	  const server = await loadServer(job);
983	  if (SANDBOX) {
984	    await sandboxAnimateJob(job.id, [
985	      { pct: 5, step: "Starting" },
986	      { pct: 25, step: "Creating archive… 25%" },
987	      { pct: 55, step: "Creating archive… 55%" },
988	      { pct: 80, step: "Creating archive… 80%" },
989	      { pct: 95, step: "Finalizing" },
990	      { pct: 100, step: "Backup complete" },
991	    ]);
992	    // Deliberately NOT stamping lastAutoBackup here: no archive exists, and the
993	    // column means "a backup was observed in storage".
994	    await notify(
995	      server.userId,
996	      `Backup simulated (sandbox) for ${server.hostname}`,
997	      "Sandbox only — no VM was contacted and no archive was written. This is not a restore point.",
998	      `/dashboard/servers/${server.id}`
999	    );
1000	    return;
1001	  }
1002	  if (server.vmid == null) {
1003	    throw new Error("backup: this server has no VMID yet, so there is nothing to back up.");
1004	  }
1005	  const vmid = server.vmid;
1006	
1007	  try {
1008	    await reportJobProgress(job.id, 2, "Starting");
1009	    const { conn } = await nodeFor(server);
1010	
1011	    // Snapshot what already exists. Membership of this set — not a timestamp
1012	    // comparison — is what makes "a new archive appeared" unarguable: ctime comes
1013	    // off the hypervisor and our window would come off the worker's clock.
1014	    const before = await listBackupsOn(conn, vmid);
1015	
1016	    const upid = await conn.post(`/nodes/${conn.node}/vzdump`, {
1017	      vmid,
1018	      storage: "backup",
1019	      mode: "snapshot",
1020	      compress: "zstd",
1021	    });
1022	    await waitForTaskProgress(
1023	      conn,
1024	      upid,
1025	      (progress, step) => reportJobProgress(job.id, progress, step),
1026	      { timeoutMs: 3_600_000, phase: "backup" }
1027	    );
1028	
1029	    await reportJobProgress(job.id, 96, "Verifying archive");
1030	    const after = await listBackupsOn(conn, vmid);
1031	    const proof = freshBackupProof({ vmid, before, after });
1032	    if (!proof.proven) throw new Error(`backup not verified — ${proof.reason}`);
1033	
1034	    await reportJobProgress(job.id, 100, "Backup complete");
1035	
1036	    // Retention: keep the latest N backups for this server (N = the paid backup
1037	    // tier's keep count, an explicit backupKeep override winning); prune the rest.
1038	    const keep = resolveBackupKeep(server.backupTier, server.backupKeep);
1039	    try {
1040	      const pruned = await pruneBackups(conn, vmid, keep);
1041	      if (pruned > 0) console.log(`[backup] pruned ${pruned} old backup(s) for vmid ${vmid} (keep ${keep})`);
1042	    } catch (e) {
1043	      console.error(`[backup] prune failed for vmid ${vmid}`, e);
1044	    }
1045	
1046	    // The ONLY writer of lastAutoBackup, and only on proof.
1047	    await db.server.update({ where: { id: server.id }, data: { lastAutoBackup: new Date() } });
1048	
1049	    await notify(
1050	      server.userId,
1051	      `Backup completed for ${server.hostname}`,
1052	      `Verified present in backup storage: ${proof.volid} (${humanBytes(proof.sizeBytes)}).`,
1053	      `/dashboard/servers/${server.id}`
1054	    );
1055	  } catch (e: any) {
