1057	    // three retries do not produce three notifications for one bad night.
1058	    if (job.attempts >= MAX_ATTEMPTS) {
1059	      await notify(
1060	        server.userId,
1061	        `Backup FAILED for ${server.hostname}`,
1062	        `${String(e?.message ?? e).slice(0, 400)} — this server has no new restore point. ` +
1063	          `Your last verified backup (if any) is shown under Backups.`,
1064	        `/dashboard/servers/${server.id}`
1065	      );
1066	    }
1067	    throw e;
1068	  }
1069	}
