1115	/**
1116	 * Refund a per-server disk expansion that was paid for but never delivered.
1117	 *
1118	 * The DISK_EXPAND handler advances `Server.extraDiskGB` only AFTER the disk has
1119	 * really grown, so that field is the ground truth for "did the customer get what
1120	 * they paid for". We refund only when it never reached the job's target — which
1121	 * also keeps this safe against the partial-success case (disk grown, filesystem
1122	 * left for the customer to grow by hand): that path completes successfully, sets
1123	 * extraDiskGB, and is therefore never refunded.
1124	 *
1125	 * Idempotent per job via the reconcile audit marker.
1126	 */
1127	async function reconcileFailedDiskExpand(job: Job) {
1128	  const p = (job.payload ?? {}) as { prorateCents?: number; addGB?: number; targetExtraDiskGB?: number };
1129	  const cents = p.prorateCents ?? 0;
1130	  if (cents <= 0 || !job.serverId) return;

1131	
1132	  const already = await db.auditLog.findFirst({
1133	    where: { action: "server.disk_expand.reconcile", detail: { contains: `job=${job.id}` } },
1134	  });
1135	  if (already) return;
1136	
1137	  const server = await db.server.findUnique({
1138	    where: { id: job.serverId },
1139	    select: { userId: true, hostname: true, extraDiskGB: true },
1140	  });
1141	  if (!server) return;
1142	
1143	  // The expansion actually landed (or a later one superseded it) — the customer
1144	  // has the storage, so the charge stands. Nothing to unwind.
1145	  const target = Number(p.targetExtraDiskGB ?? 0);
1146	  if (target > 0 && server.extraDiskGB >= target) return;
1147	
1148	  try {
1149	    await db.$transaction([
1150	      db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
1151	      db.walletTransaction.create({
1152	        data: {
1153	          userId: server.userId,
1154	          amountCents: cents,
1155	          description: `Refund: failed storage expansion (+${p.addGB ?? "?"} GB) — ${server.hostname}`,
1156	        },
1157	      }),
1158	      db.notification.create({
1159	        data: {
1160	          userId: server.userId,
1161	          title: `Storage expansion failed on ${server.hostname} — refunded`,
1162	          body: `We couldn't add the storage, so $${(cents / 100).toFixed(2)} has been credited back to your wallet. Your server and its data are untouched.`,
1163	          href: `/dashboard/servers/${job.serverId}`,
1164	        },
1165	      }),
1166	    ]);
1167	    await db.auditLog.create({
1168	      data: {
1169	        userId: server.userId,
1170	        action: "server.disk_expand.reconcile",
1171	        detail: `job=${job.id} addGB=${p.addGB} cents=${cents}`,
1172	      },
1173	    });
1174	  } catch (e: any) {
1175	    await db.auditLog
1176	      .create({
1177	        data: {
1178	          userId: server.userId,
1179	          action: "server.disk_expand.reconcile.uncharged",
1180	          detail: `job=${job.id} cents=${cents} :: ${e?.message ?? e}`,
1181	        },
1182	      })
1183	      .catch(() => {});
1184	  }
1185	}
