1187	/**
1188	 * Reverse a money side-effect that a job committed up-front but never delivered.
1189	 * Server actions charge/credit the wallet before enqueuing the worker job (so the
1190	 * UI reflects the change immediately); if the job then fails terminally the money
1191	 * must be unwound or the customer is charged for a resize that never happened
1192	 * (up) or keeps a downgrade credit for hardware they still have (down).
1193	 * Idempotent per job: guarded by the RECONCILED audit marker so a re-run can't
1194	 * double-reverse.
1195	 */
1196	async function reconcileFailedJob(job: Job) {
1197	  if (job.type === "DISK_EXPAND") return reconcileFailedDiskExpand(job);
1198	  if (job.type !== "RESIZE") return;
1199	  const p = (job.payload ?? {}) as { prorateCents?: number; direction?: "up" | "down" };
1200	  const cents = p.prorateCents ?? 0;
1201	  if (cents <= 0 || !job.serverId) return;
1202	
1203	  // Idempotency: skip if we already reversed this exact job.
1204	  const already = await db.auditLog.findFirst({
1205	    where: { action: "server.resize.reconcile", detail: { contains: `job=${job.id}` } },
1206	  });
1207	  if (already) return;
1208	
1209	  const server = await db.server.findUnique({ where: { id: job.serverId }, select: { userId: true, hostname: true } });
1210	  if (!server) return;
1211	
1212	  try {
1213	    if (p.direction === "up") {
1214	      // Upgrade charge never delivered → refund the prorated charge.
1215	      await db.$transaction([
1216	        db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
1217	        db.walletTransaction.create({
1218	          data: { userId: server.userId, amountCents: cents, description: `Refund: failed upgrade — ${server.hostname}` },
1219	        }),
1220	      ]);
1221	    } else if (p.direction === "down") {
1222	      // Downgrade credit was given but hardware unchanged → claw the credit back.
1223	      // Guarded so it can never drive the balance negative; if the customer already
1224	      // spent it, we log and leave it (best-effort — they keep a small windfall).
1225	      await db.$transaction(async (tx) => {
1226	        await debitWallet(tx, server.userId, cents);
1227	        await tx.walletTransaction.create({
1228	          data: { userId: server.userId, amountCents: -cents, description: `Reversed downgrade credit (resize failed) — ${server.hostname}` },
1229	        });
1230	      });
1231	    }
1232	    await db.auditLog.create({
1233	      data: { userId: server.userId, action: "server.resize.reconcile", detail: `job=${job.id} dir=${p.direction} cents=${cents}` },
1234	    });
1235	  } catch (e: any) {
1236	    // InsufficientBalanceError on a down-reversal is expected/acceptable; record it.
1237	    await db.auditLog.create({
1238	      data: { userId: server.userId, action: "server.resize.reconcile.uncharged", detail: `job=${job.id} dir=${p.direction} cents=${cents} :: ${e?.message ?? e}` },
1239	    }).catch(() => {});
1240	  }
1241	}
