1243	async function runJob(job: Job) {
1244	  // The job is already atomically claimed (status RUNNING, attempts incremented)
1245	  // by the loop's compare-and-swap before we get here — see the CAS in main().
1246	  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
1247	  try {
1248	    await handlers[job.type](job);
1249	    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
1250	    console.log(`[worker] job ${job.id} DONE`);
1251	  } catch (e: any) {
1252	    let error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`;
1253	    // Defense in depth: a child process (e.g. `sshpass -p <rootPassword> …`) can
1254	    // leak the server's root password into the thrown message. Redact it before
1255	    // it is persisted to Job.error. Redact BEFORE slicing so a truncation can't
1256	    // sever the match. Best-effort — never let redaction lookup fail the job path.
1257	    if (job.serverId) {
1258	      try {
1259	        const s = await db.server.findUnique({
1260	          where: { id: job.serverId },
1261	          select: { rootPassword: true, rootPasswordEnc: true },
1262	        });
1263	        const pw = s ? serverRootPassword(s) : null;
1264	        if (pw) error = error.split(pw).join("***");
1265	      } catch {
1266	        /* best-effort redaction */
1267	      }
1268	    }
1269	    error = error.slice(0, 2000);
1270	    console.error(`[worker] job ${job.id} FAILED: ${error}`);
1271	    const current = await db.job.findUnique({ where: { id: job.id } });
1272	    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
1273	    await db.job.update({
1274	      where: { id: job.id },
1275	      data: { status: retriable ? "QUEUED" : "FAILED", error },
1276	    });
1277	    if (!retriable) {
1278	      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
1279	      // Persist terminal job failures to ErrorLog (deduped by fingerprint) so the
1280	      // admin Error Logs view surfaces what broke on the customer side, not just
1281	      // the transient Job.error. logError is already non-throwing; guard anyway.
1282	      await logError(`job.${String(job.type).toLowerCase()}`, new Error(error), {
1283	        source: "job",
1284	        jobId: job.id,
1285	        serverId: job.serverId ?? undefined,
1286	      }).catch(() => {});
1287	      if (job.serverId) {
1288	        const stillExists = await db.server.findUnique({ where: { id: job.serverId } });
1289	        if (stillExists) {
1290	          // Only jobs that actually change the VM's run/disk state should strand the
1291	          // server in ERROR. Side operations — backup, snapshot-create, the control-
1292	          // panel db/website/app/cron/service ops, SSL, migrate copy, game update —
1293	          // never touch the VM's run state; their failures surface via the executor's
1294	          // own notification and must NOT flip the whole server to ERROR (a failed
1295	          // backup was wrongly making the server look like it had shut down).
1296	          if (VM_STATE_FAILURE_JOBS.has(job.type)) {
