126	export async function nodeCapacitySweep(): Promise<void> {
127	  if (SANDBOX) return; // no real nodes to size in the sandbox
128	
129	  const t = await nodeThresholds();
130	
131	  let utils: NodeUtil[];
132	  try {
133	    const [proxmox, hosting] = await Promise.all([proxmoxNodeUtil(t), hostingNodeUtil(t)]);
134	    utils = [...proxmox, ...hosting];
135	  } catch (e) {
136	    console.error("[node-capacity] utilization compute error", e);
137	    return;
138	  }
139	
140	  let open: Array<{
141	    id: string;
142	    nodeKind: string;
143	    nodeId: string;
144	    dimension: string;
145	    severity: string;
146	    lastNotifiedAt: Date | null;
147	  }>;
148	  try {
149	    open = await db.nodeAlert.findMany({
150	      where: { status: "OPEN" },
151	      select: { id: true, nodeKind: true, nodeId: true, dimension: true, severity: true, lastNotifiedAt: true },
152	    });
153	  } catch (e) {
154	    console.error("[node-capacity] could not read open alerts", e);
155	    return;
156	  }
157	  const openByKey = new Map(open.map((a) => [`${a.nodeKind}:${a.nodeId}:${a.dimension}`, a]));
158	
159	  const now = new Date();
160	  const cooldownMs = NODE_CAP_COOLDOWN_HOURS * 60 * 60_000;
161	  const floor = resolveFloor(t);
162	  // Every (kind,id,dimension) we actually evaluated this sweep — so a dimension
163	  // that was merely ABSENT (e.g. Proxmox unreachable, so no CPU/DISK reading) is
164	  // never mistaken for "recovered".
165	  const evaluated = new Set<string>();
166	  const nodeIds = new Set(utils.map((u) => `${u.kind}:${u.id}`));
167	
168	  for (const nu of utils) {
169	    for (const d of nu.dims) {
170	      const key = `${nu.kind}:${nu.id}:${d.dimension}`;
171	      evaluated.add(key);
172	      const sev = severityFor(d.pct, t);
173	      const existing = openByKey.get(key);
174	      const roundedPct = Math.round(d.pct);
175	      const metric = {
176	        allocPct: d.allocPct === null ? null : Math.round(d.allocPct),
177	        realPct: d.realPct === null ? null : Math.round(d.realPct),
178	        warnPct: t.warnPct,
179	        critPct: t.critPct,
180	      };
