368	/**
369	 * Last counter sample per `serverId:vmid`, in worker memory.
370	 *
371	 * Deliberately not persisted: prisma/schema.prisma has no column for a raw
372	 * per-VM counter, and the two obvious substitutes are worse than a cold start —
373	 * the `Setting` KV is handed wholesale to the admin settings page (it would ship
374	 * a blob of every server's counters to the browser), and reusing
375	 * `abuseBwMark` would break the abuse window it exists for. A worker restart
376	 * therefore loses the baseline; `backfillGap` recovers the interval from RRD so
377	 * the restart costs at most the newest (still-filling) RRD bucket instead of a
378	 * whole sweep interval.
379	 *
380	 * Keyed by vmid as well as serverId so a reinstall or migration onto a different
381	 * vmid can never be compared against the old VM's counters.
382	 */
383	const bwBaselines = new Map<string, BwSample>();
384	
385	/**
386	 * Where the last sweep stopped. The sweep is time-bounded, so on a large fleet it
387	 * may not reach every server; resuming from the cursor rather than always
388	 * restarting at the first row is what stops the tail of the list from being
389	 * silently never metered — a server whose usage always reads 0 because nobody
390	 * ever looked at it is precisely the failure this whole change exists to fix.
391	 */
392	let bwCursor = 0;
393	
394	/**
395	 * Sampling runs INLINE in the worker's strictly serial job loop: every second
396	 * spent here is a second no customer job runs, so the sweep is hard-bounded.
397	 * A Proxmox node that hangs must cost one timeout, not the queue.
398	 */
399	const BW_CALL_TIMEOUT_MS = 8_000;
400	const BW_SWEEP_BUDGET_MS = 45_000;
401	/** RRD back-fill is ~10x the payload of a status read, so cap it per sweep. */
402	const BW_MAX_BACKFILLS_PER_SWEEP = 50;
403	/** Below this a gap is not worth an extra API call. */
404	const BW_BACKFILL_MIN_GAP_MS = 2 * 60_000;
405	/** `timeframe=hour` holds 60 x 60s buckets; beyond that the gap is unrecoverable. */
406	const BW_RRD_WINDOW_MS = 60 * 60_000;
407	
408	/**
409	 * Bound one Proxmox call. Note this abandons the promise rather than cancelling
410	 * the request (lib/proxmox takes no AbortSignal) — the point is that the sweep
411	 * moves on, not that the socket closes.
412	 */
413	function withTimeout<T>(p: Promise<T>, ms: number, what: string): Promise<T> {
414	  return new Promise<T>((resolve, reject) => {
415	    const timer = setTimeout(
416	      () => reject(new Error(`proxmox call timed out after ${ms}ms: ${what}`)),
417	      ms
418	    );
419	    p.then(
420	      (v) => {
421	        clearTimeout(timer);
422	        resolve(v);
423	      },
424	      (e) => {
425	        clearTimeout(timer);
426	        reject(e);
427	      }
428	    );
429	  });
430	}
