434	/**
435	 * Meter every RUNNING VM's network counters onto its Server row.
436	 *
437	 * Writes `bwInBytes` / `bwOutBytes` (cumulative for the current metering period)
438	 * and `bwWindowStart` (the period marker). Nothing wrote these before, which is
439	 * why the customer's bandwidth panel read a permanent zero and worker/abuse.ts
440	 * could never fire — see lib/bandwidth.ts for the full history.
441	 *
442	 * READ-ONLY against Proxmox: `status/current` and `rrddata`, never a mutation.
443	 * Best-effort per server — one unreachable node must not cost the whole sweep.
444	 */
445	export async function sampleServerBandwidth(): Promise<void> {
446	  if (SANDBOX) return; // no real VMs, therefore no real traffic to meter
447	
448	  const sweepStartMs = Date.now();
449	  let health;
450	  try {
451	    health = await readBwMeterHealth(sweepStartMs);
452	  } catch (e) {
453	    console.error("[bandwidth] could not read meter markers", e);
454	    return;
455	  }
456	  // End of the previous sweep — where a cold-start back-fill starts counting.
457	  // Only the cold path uses it; the warm path uses each baseline's own
458	  // timestamp, so a sweep cadence that drifts (or a sweep that gets skipped
459	  // entirely) stays correct without assuming a fixed interval.
460	  const priorSweepMs = health.lastAt?.getTime() ?? null;
461	
462	  let servers: Array<{
463	    id: string;
464	    hostname: string;
465	    vmid: number | null;
466	    bwWindowStart: Date;
467	    node: {
468	      pveNode: string;
469	      apiUrl: string;
470	      tokenId: string;
471	      tokenSecret: string;
472	    } | null;
473	  }>;
474	  try {
475	    servers = await db.server.findMany({
476	      where: { status: "RUNNING", vmid: { not: null } },
477	      select: {
478	        id: true,
479	        hostname: true,
480	        vmid: true,
481	        bwWindowStart: true,
482	        node: { select: { pveNode: true, apiUrl: true, tokenId: true, tokenSecret: true } },
483	      },
484	      orderBy: { id: "asc" }, // stable order, so the cursor below means something
485	    });
486	  } catch (e) {
487	    console.error("[bandwidth] list servers error", e);
488	    return;
489	  }
490	
491	  // On the very first sweep there is no stored start yet; treat now as the start
492	  // so window normalisation below has a truthful lower bound to work with.
493	  const startedAtMs = health.startedAt?.getTime() ?? sweepStartMs;
494	
495	  let sampled = 0;
496	  let backfills = 0;
497	  let backfilled = false;
498	  let gapDetected = false;
499	
500	  // Every RUNNING VM's key, whether or not this sweep reaches it, so the prune at
501	  // the end can't throw away a baseline we still want.
502	  const liveKeys = new Set(
503	    servers.filter((s) => s.vmid != null).map((s) => `${s.id}:${s.vmid}`)
504	  );
505	
506	  const total = servers.length;
507	  const startIdx = total > 0 ? bwCursor % total : 0;
508	  let visited = 0;
509	
510	  for (let i = 0; i < total; i++) {
511	    const s = servers[(startIdx + i) % total];
512	    if (s.vmid == null) {
513	      visited++;
514	      continue;
515	    }
516	    const key = `${s.id}:${s.vmid}`;
517	
518	    if (Date.now() - sweepStartMs > BW_SWEEP_BUDGET_MS) {
519	      // Out of budget. Baselines are kept, so the servers we skipped are simply
520	      // metered over a longer interval next sweep — no traffic is lost — and the
521	      // cursor makes the next sweep start where this one stopped.
522	      console.warn(
523	        `[bandwidth] sweep budget exhausted after ${visited} of ${total} servers; ` +
524	          `resuming from there next sweep`
525	      );
526	      break;
527	    }
528	    visited++;
529	
530	    const client: BwClient = s.node
531	      ? pveFor({
532	          apiUrl: s.node.apiUrl,
533	          pveNode: s.node.pveNode,
534	          tokenId: s.node.tokenId,
535	          tokenSecret: s.node.tokenSecret,
536	        })
537	      : pve;
538	    const pnode = s.node?.pveNode ?? defaultNode;
539	
540	    try {
541	      const cur = await withTimeout(
542	        client.get(`/nodes/${pnode}/qemu/${s.vmid}/status/current`),
543	        BW_CALL_TIMEOUT_MS,
544	        `status/current vm ${s.vmid}`
545	      );
546	      // Our DB says RUNNING but Proxmox is authoritative. A stopped VM reports
547	      // netin/netout 0, and treating that as a counter rollback would be noise.
548	      if (String(cur?.status ?? "") !== "running") {
549	        bwBaselines.delete(key);
550	        continue;
551	      }
552	      const netin = Number(cur?.netin);
553	      const netout = Number(cur?.netout);
554	      if (!Number.isFinite(netin) || !Number.isFinite(netout)) {
555	        // Node too old / unexpected payload: no counters, nothing to meter.
556	        continue;
557	      }
558	      const sample: BwSample = {
559	        netin,
560	        netout,
561	        uptimeSec: Number(cur?.uptime) || 0,
562	        pid: Number.isFinite(Number(cur?.pid)) ? Number(cur.pid) : null,
563	        atMs: Date.now(),
564	      };
565	
566	      const prev = bwBaselines.get(key);
567	      bwBaselines.set(key, sample);
568	      sampled++;
569	
570	      let inBytes = 0;
571	      let outBytes = 0;
572	
573	      if (prev) {
574	        const credit = creditFromCounters(prev, sample);
575	        inBytes = credit.inBytes;
576	        outBytes = credit.outBytes;
577	        if (credit.reason !== "delta") {
578	          // Logged, never silent: each of these means the customer's total is
579	          // missing traffic we could not attribute, and an operator chasing a
580	          // suspiciously low figure needs to see it.
581	          console.warn(
582	            `[bandwidth] ${s.hostname} (vm ${s.vmid}) counter ${credit.reason} — ` +
583	              `credited ${inBytes} in / ${outBytes} out (prev ${prev.netin}/${prev.netout} ` +
584	              `pid ${prev.pid} up ${prev.uptimeSec}s → now ${sample.netin}/${sample.netout} ` +
585	              `pid ${sample.pid} up ${sample.uptimeSec}s)`
586	          );
587	        }
588	      } else if (priorSweepMs !== null) {
589	        // Cold start (worker restarted, or this VM just came up). The counter
590	        // baseline is gone, so recover the interval from RRD rate data instead
591	        // of dropping it — without this, every redeploy silently erases up to a
592	        // sweep interval of every customer's usage.
593	        const gapMs = sweepStartMs - priorSweepMs;
594	        if (gapMs > BW_RRD_WINDOW_MS) {
595	          // Longer than RRD's hour window: part of this gap is unrecoverable.
596	          // Recorded so the UI can admit the period under-reports.
597	          gapDetected = true;
598	        }
599	        if (gapMs >= BW_BACKFILL_MIN_GAP_MS && backfills < BW_MAX_BACKFILLS_PER_SWEEP) {
600	          backfills++;
601	          const filled = await backfillGap(client, pnode, s.vmid, priorSweepMs, sample.atMs);
602	          if (filled) {
603	            inBytes = filled.inBytes;
604	            outBytes = filled.outBytes;
605	            backfilled = true;
606	          }
607	        }
608	      }
609	
610	      const roundedIn = Math.max(0, Math.round(inBytes));
611	      const roundedOut = Math.max(0, Math.round(outBytes));
612	
613	      // The period marker predates metering on every row created before this
614	      // sweep existed (it defaults to the row's creation date), so pull it
615	      // forward to the moment measurement actually began. Without this the UI
616	      // would claim these bytes cover months we never watched.
617	      const needsWindowFix = s.bwWindowStart.getTime() < startedAtMs;
618	      const effectiveWindowMs = Math.max(s.bwWindowStart.getTime(), startedAtMs);
619	      const roll = sample.atMs - effectiveWindowMs >= BW_PERIOD_MS;
620	
621	      if (roundedIn === 0 && roundedOut === 0 && !roll && !needsWindowFix) {
622	        continue; // nothing to record — skip the write entirely
623	      }
624	
625	      if (roll) {
626	        // New period: these bytes belong to the period starting now.
627	        await db.server.update({
628	          where: { id: s.id },
629	          data: {
630	            bwInBytes: BigInt(roundedIn),
631	            bwOutBytes: BigInt(roundedOut),
632	            bwWindowStart: new Date(sample.atMs),
633	          },
634	        });
635	      } else {
636	        await db.server.update({
637	          where: { id: s.id },
638	          data: {
639	            bwInBytes: { increment: BigInt(roundedIn) },
640	            bwOutBytes: { increment: BigInt(roundedOut) },
641	            ...(needsWindowFix ? { bwWindowStart: new Date(startedAtMs) } : {}),
642	          },
643	        });
644	      }
645	    } catch (e) {
646	      console.error(`[bandwidth] sample error for ${s.hostname} (vm ${s.vmid})`, e);
647	    }
648	  }
649	
650	  bwCursor = total > 0 ? (startIdx + visited) % total : 0;
651	
652	  // Drop baselines for VMs no longer in the RUNNING set (deleted, stopped,
653	  // suspended, reinstalled onto a new vmid) so the map stays bounded. Servers
654	  // skipped by the time budget ARE in liveKeys, so their baselines survive.
655	  for (const key of [...bwBaselines.keys()]) {
656	    if (!liveKeys.has(key)) bwBaselines.delete(key);
657	  }
658	
659	  try {
660	    await recordBwSweep({
661	      sweepEndMs: Date.now(),
662	      sampled,
663	      candidates: total,
664	      gapDetected,
665	      backfilled,
666	      hadStartedAt: health.startedAt !== null,
667	    });
668	  } catch (e) {
669	    console.error("[bandwidth] could not record sweep markers", e);
670	  }
671	}
