673	/**
674	 * Recover a metering gap for one VM from RRD rate data.
675	 *
676	 * Returns null (rather than 0) when RRD had nothing usable, so the caller does
677	 * not treat "no data" as "no traffic". Bounded by the same per-call timeout as
678	 * the counter read.
679	 */
680	async function backfillGap(
681	  client: BwClient,
682	  pnode: string,
683	  vmid: number,
684	  fromMs: number,
685	  toMs: number
686	): Promise<{ inBytes: number; outBytes: number } | null> {
687	  try {
688	    const rows = await withTimeout(
689	      client.get(`/nodes/${pnode}/qemu/${vmid}/rrddata`, { timeframe: "hour", cf: "AVERAGE" }),
690	      BW_CALL_TIMEOUT_MS,
691	      `rrddata vm ${vmid}`
692	    );
693	    const filled = integrateRrdBytes(
694	      Array.isArray(rows) ? rows : [],
695	      Math.floor(fromMs / 1000),
696	      Math.floor(toMs / 1000)
697	    );
698	    if (!filled) return null;
699	    return { inBytes: filled.inBytes, outBytes: filled.outBytes };
700	  } catch (e) {
701	    console.error(`[bandwidth] rrd back-fill failed for vm ${vmid}`, e);
702	    return null;
703	  }
704	}
