706	export async function monitorSweep(): Promise<void> {
707	  if (SANDBOX) return; // no real nodes/Proxmox to monitor in the sandbox
708	
709	  // 0. Bandwidth metering. Runs FIRST and inside monitorSweep on purpose:
710	  //    worker/index.ts calls monitorSweep() and then abuseSweep() in the same
711	  //    block, so metering this way guarantees the abuse detector reads counters
712	  //    from this sweep rather than the previous one — and needs no change to the
713	  //    worker loop, which other work owns.
714	  try {
715	    await sampleServerBandwidth();
716	  } catch (e) {
717	    console.error("[bandwidth] sweep error", e);
718	  }
719	  // 1. Node disk usage > threshold
720	  try {
721	    const storage = await nodeStorageUsage();
722	    for (const s of storage) {
723	      if (s.reachable && s.total > 0 && s.ratio > DISK_WARN_RATIO) {
724	        const pct = Math.round(s.ratio * 100);
725	        await notifyAdmins(
726	          `Disk capacity warning — ${s.node}/${s.storage} at ${pct}%`,
727	          `Storage "${s.storage}" on node ${s.node} is ${pct}% full ` +
728	            `(${(s.avail / 1024 ** 3).toFixed(0)} GB free). Free space or add capacity to keep provisioning healthy.`
729	        );
730	      }
731	    }
732	  } catch (e) {
733	    console.error("[monitor] disk check error", e);
734	  }
735	
736	  // 2. Node RAM pressure > threshold
737	  try {
738	    const ram = await nodeRamUsage();
739	    for (const r of ram) {
740	      if (r.reachable && r.total > 0 && r.ratio > RAM_WARN_RATIO) {
741	        const pct = Math.round(r.ratio * 100);
742	        await notifyAdmins(
743	          `Memory pressure — ${r.node} at ${pct}%`,
744	          `Node ${r.node} RAM is ${pct}% used. New deploys may be refused until usage drops.`
745	        );
746	      }
747	    }
748	  } catch (e) {
749	    console.error("[monitor] ram check error", e);
750	  }
751	
752	  // 3. Stuck jobs (RUNNING beyond the stuck threshold)
753	  try {
754	    const stuck = await stuckJobs();
755	    if (stuck.length > 0) {
756	      const mins = Math.round(STUCK_JOB_MS / 60_000);
757	      const lines = stuck
758	        .slice(0, 8)
759	        .map(
760	          (j) =>
761	            `• ${j.type}${j.hostname ? ` (${j.hostname})` : ""} — running ${fmtAge(
762	              Date.now() - j.updatedAt.getTime()
763	            )}`
764	        )
765	        .join("\n");
766	      await notifyAdmins(
767	        `Stuck jobs — ${stuck.length} running > ${mins}m`,
768	        `The worker has job(s) stuck in RUNNING:\n${lines}`
769	      );
770	    }
771	  } catch (e) {
772	    console.error("[monitor] stuck-job check error", e);
773	  }
774	
775	  // 4. Worker liveness + pending-job backlog
776	  try {
777	    const wh = await workerHealth();
778	    if (wh.status === "down") {
779	      await notifyAdmins(
780	        "Worker appears stopped",
781	        wh.detail + ". Check the provisioning worker process."
782	      );
783	    }
784	    if (wh.queuedBacklog >= QUEUE_BACKLOG_ALERT) {
785	      await notifyAdmins(
786	        `Job backlog building — ${wh.queuedBacklog} queued`,
787	        `${wh.queuedBacklog} jobs are waiting in the queue. The worker may be overloaded or slow.`
788	      );
789	    }
790	  } catch (e) {
791	    console.error("[monitor] worker check error", e);
792	  }
793	
794	  // 5. Backup freshness (best-effort; skipped if backup storage isn't listable)
795	  try {
796	    const bk = await backupSummary();
797	    if (bk.reachable && bk.count > 0 && bk.newestCtime !== null) {
798	      const ageMs = Date.now() - bk.newestCtime * 1000;
799	      if (ageMs > BACKUP_STALE_MS) {
800	        await notifyAdmins(
801	          `Backups look stale — newest is ${fmtAge(ageMs)} old`,
802	          `The most recent backup on disk is ${fmtAge(ageMs)} old. Verify the backup schedule is running.`
803	        );
804	      }
805	    }
806	  } catch (e) {
807	    console.error("[monitor] backup check error", e);
808	  }
809	
810	  // 6. Node capacity warnings — per-node utilization (allocation + real usage)
811	  //    vs the admin WARN/CRITICAL thresholds, debounced against OPEN NodeAlert
812	  //    rows so a filling node is surfaced before provisioning fails. Kept LAST so
813	  //    a slow multi-node Proxmox poll can't delay the cheaper checks above.
814	  try {
815	    await nodeCapacitySweep();
816	  } catch (e) {
817	    console.error("[node-capacity] sweep error", e);
818	  }
819	}
