5	/**
6	 * Scheduled-backup sweep.
7	 *
8	 * `scheduledBackupSweep` finds RUNNING servers that opted into recurring backups
9	 * (`autoBackup=true`) whose last backup ATTEMPT is older than their configured
10	 * cadence (or which have never had one), and enqueues a BACKUP_CREATE job for
11	 * each — de-duping on any in-flight job so it's safe to call on a timer.
12	 *
13	 * It deliberately writes NOTHING to `Server.lastAutoBackup`. That used to be
14	 * stamped right here, at enqueue time, which is how a customer could read "Last
15	 * automatic backup: today" every night while vzdump silently failed every night
16	 * (incident H4). The column now means "an archive was observed in storage", and
17	 * `backupCreate` in worker/index.ts is its only writer. All the decision logic
18	 * lives in lib/backup-verify.ts so it can be tested without a DB or a clock.
19	 *
20	 * NOTE: `worker/index.ts` owns the job loop; it already knows how to run
21	 * BACKUP_CREATE jobs. Wire this sweep into the main loop on a timer, e.g.:
22	 *
23	 *   import { scheduledBackupSweep } from "./backup-schedule";
24	 *   if (Date.now() - lastBackupSweep > 15 * 60_000) {
25	 *     lastBackupSweep = Date.now();
26	 *     try { await scheduledBackupSweep(); } catch (e) { console.error(e); }
27	 *   }
28	 */
29	export async function scheduledBackupSweep(): Promise<void> {
30	  if (SANDBOX) return; // no real backups run in the sandbox
31	  const now = Date.now();
32	
33	  const candidates = await db.server.findMany({
34	    where: {
35	      status: "RUNNING",
36	      autoBackup: true,
37	      backupIntervalHours: { not: null },
38	    },
39	    select: {
40	      id: true,
41	      hostname: true,
42	      backupIntervalHours: true,
43	      lastAutoBackup: true,
44	    },
45	  });
46	  if (candidates.length === 0) return;
47	
48	  // One row per server: the most recent BACKUP_CREATE job, whatever its outcome.
49	  // This is the attempt anchor — see `isAutoBackupDue` for why anchoring on
50	  // success instead would hammer a server whose backups always fail.
51	  const lastAttempts = await db.job.findMany({
52	    where: { serverId: { in: candidates.map((s) => s.id) }, type: "BACKUP_CREATE" },
53	    orderBy: { createdAt: "desc" },
54	    distinct: ["serverId"],
55	    select: { serverId: true, createdAt: true, status: true },
56	  });
57	  const attemptBy = new Map(lastAttempts.map((j) => [j.serverId as string, j]));
58	
